    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_count = 0
    rich_count = 0
    cindy_like = False

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 100:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 100:
                    dangerous_count += 1
                if bid >= 140:
                    cindy_like = True

    if not alive:
        return float(min(budget, 8.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if supply <= 16:
        urgency += 2
    elif supply <= 19:
        urgency += 1
    elif supply >= 23:
        urgency -= 1

    if rich_count == 0:
        urgency -= 1

    if hp >= 8 and no_water_days == 0 and supply <= 18 and cindy_like:
        return float(min(budget, 0.0))

    if urgency <= 0:
        base = 12.0 if supply >= 22 else 18.0
        if highest_prev < 40:
            base = max(base, highest_prev + 2.0)
        return float(min(budget, base))

    if urgency == 1:
        base = 28.0 if supply >= 20 else 36.0
        if highest_prev < 60:
            base = max(base, highest_prev + 3.0)
        return float(min(budget, base))

    if urgency == 2:
        if cindy_like and supply <= 18 and hp > 4 and no_water_days == 0:
            return float(min(budget, 22.0))
        base = 48.0 if supply >= 20 else 58.0
        if highest_prev < 80:
            base = max(base, highest_prev + 4.0)
        return float(min(budget, base))

    if urgency == 3:
        base = 72.0 if supply >= 20 else 86.0
        if highest_prev < 100:
            base = max(base, highest_prev + 5.0)
        return float(min(budget, base))

    if urgency == 4:
        base = 95.0 if supply >= 20 else 112.0
        if highest_prev < 120:
            base = max(base, highest_prev + 6.0)
        return float(min(budget, base))

    base = 125.0 if supply >= 20 else 151.0
    if highest_prev > 0:
        base = max(base, highest_prev + 1.0)
    return float(min(budget, base))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp is not None and opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Supply pressure estimate: higher supply => bid less.
    # Normalize within [MIN_SUPPLY, MAX_SUPPLY]
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base bid: moderate, scaled down when supply is plentiful.
    # Also react to low hp / accumulating no-water days.
    urgency = 0.0
    if my_hp <= 2.0:
        urgency += 1.0
    if my_hp <= 4.0:
        urgency += 0.5
    if my_no_water_days >= 2:
        urgency += 0.5
    if my_no_water_days >= 3:
        urgency += 0.5

    base = DAILY_SALARY * (0.62 - 0.25 * supply_norm)
    bid = base + urgency * (DAILY_SALARY * 0.25)

    # If someone previously overbid massively (like Cindy), avoid matching exactly unless we must.
    # Use thresholds relative to DAILY_SALARY.
    if highest_prev_bid >= DAILY_SALARY * 1.4:
        if my_hp > 4.0 and my_no_water_days <= 1:
            # Don't start a price war; slight undercut
            bid = min(bid, second_prev_bid + 1.0 if second_prev_bid > 0 else bid)
        else:
            # Need water soon; raise but still capped
            bid = max(bid, DAILY_SALARY * 0.95)
    elif highest_prev_bid >= DAILY_SALARY * 0.8:
        # Medium pressure: bid around the top-1 neighborhood
        bid = max(bid, min(highest_prev_bid + 1.5, DAILY_SALARY * 1.05))

    # Ensure we don't exceed budget and never negative
    bid = max(0.0, min(my_budget, bid))

    # If budget is tiny, still bid something nonzero to secure if possible
    if bid <= 0.0 and my_budget > 0.0:
        bid = min(my_budget, 1.0)

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    day_factor = day_context['day'] / EPISODE_DAYS
    base_bid = DAILY_SALARY * (0.4 + 0.5 * day_factor)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.80:
            if my_status['hp'] > 4:
                return min(my_status['budget'], max(base_bid, highest_prev_bid + 1.0))
            else:
                return min(my_status['budget'], max(DAILY_SALARY * 0.9, highest_prev_bid + 1.0))
        else:
            return min(my_status['budget'], max(base_bid, highest_prev_bid + 1.0))

    return min(my_status['budget'], base_bid)

